# ============================================================
# _strip_accents — NFKD + manual replacements
# ============================================================

def _strip_accents(text):
    """Remove accents from text."""
    manual = {
        '\u0142': 'l', '\u0141': 'L',  # ł, Ł
        '\u00f8': 'o', '\u00d8': 'O',  # ø, Ø
        '\u00f0': 'd', '\u00d0': 'D',  # ð, Ð
        '\u00fe': 'th', '\u00de': 'Th',  # þ, Þ
        '\u00df': 'ss',  # ß
        '\u0111': 'd', '\u0110': 'D',  # đ, Đ
        '\u0131': 'i', '\u0130': 'I',  # ı, İ
    }
    for char, replacement in manual.items():
        text = text.replace(char, replacement)
    text = unicodedata.normalize('NFKD', text)
    text = ''.join(c for c in text if not unicodedata.combining(c))
    return text

# ============================================================
# _auto_normalize — strip safe suffixes/prefixes if result is known
# ============================================================

_SAFE_SUFFIXES = frozenset({
    'fc', 'sc', 'cf', 'afc', 'utd', 'ac', 'ss', 'sd',
    'fk', 'nk', 'bk', 'if', 'il', 'ek', 'as', 'rc',
})

_SAFE_PREFIXES = frozenset({
    'asu', 'csa', 'clb', 'cd', 'ca', 'ce', 'cs',
    'rcd', 'rcc', 'gnk', 'gd', 'gc', 'ac', 'af',
})

_SAFE_PREPS = frozenset({
    'de', 'del', 'da', 'do', 'dos', 'las', 'los',
    'el', 'la', 'di', 'al', 'en',
})

def _auto_normalize(key):
    """Strip safe suffixes/prefixes if result is a known canonical."""
    if not key or key in _KNOWN_CANONICAL:
        return key
    tokens = key.split('_')
    if len(tokens) < 2:
        return key
    # Strip trailing suffix
    if tokens[-1] in _SAFE_SUFFIXES and len(tokens) >= 2:
        candidate = '_'.join(tokens[:-1])
        if candidate in _KNOWN_CANONICAL:
            return candidate
    # Strip prefix
    if tokens[0] in _SAFE_PREFIXES and len(tokens) >= 2:
        candidate = '_'.join(tokens[1:])
        if candidate in _KNOWN_CANONICAL:
            return candidate
    # Strip prepositions from middle
    if len(tokens) >= 3:
        filtered = [t for t in tokens if t not in _SAFE_PREPS]
        if filtered and len(filtered) < len(tokens):
            candidate = '_'.join(filtered)
            if candidate in _KNOWN_CANONICAL:
                return candidate
    return key

# ============================================================
# _fuzzy_match — SequenceMatcher >= 0.92 against known canonicals
# ============================================================

def _fuzzy_match(key):
    """Find closest known canonical by fuzzy matching."""
    if not key or len(key) < 3:
        return None
    best_score = 0.0
    best_match = None
    for canonical in _KNOWN_CANONICAL:
        if abs(len(canonical) - len(key)) > max(len(key), len(canonical)) * 0.15:
            continue
        score = SequenceMatcher(None, key, canonical).ratio()
        if score > best_score:
            best_score = score
            best_match = canonical
    if best_score >= 0.92:
        return best_match
    return None

# ============================================================
# clean_team_name — 8-step normalization pipeline
# ============================================================

def clean_team_name(raw):
    """Normalize a team name to its canonical form."""
    if raw is None:
        return ""
    key = raw.lower().strip()
    if not key:
        return ""
    # Step 1: Direct alias lookup
    if key in TEAM_ALIASES:
        return TEAM_ALIASES[key]
    # Step 2: Normalize separators
    norm = key.replace('-', '_').replace('/', '_').replace(' ', '_')
    while '__' in norm:
        norm = norm.replace('__', '_')
    norm = norm.strip('_')
    if norm != key:
        if norm in TEAM_ALIASES:
            return TEAM_ALIASES[norm]
    # Step 3: Accent-stripped alias lookup
    stripped = _strip_accents(key)
    if stripped != key:
        if stripped in TEAM_ALIASES:
            return TEAM_ALIASES[stripped]
        # Step 4: Accent-stripped + normalized
        stripped_norm = stripped.replace('-', '_').replace('/', '_').replace(' ', '_')
        while '__' in stripped_norm:
            stripped_norm = stripped_norm.replace('__', '_')
        stripped_norm = stripped_norm.strip('_')
        if stripped_norm in TEAM_ALIASES:
            return TEAM_ALIASES[stripped_norm]
        key = stripped_norm
    else:
        key = norm
    # Step 5: Auto-normalize (strip safe suffixes/prefixes)
    candidate = _auto_normalize(key)
    if candidate in _KNOWN_CANONICAL:
        return candidate
    if candidate != key and candidate in TEAM_ALIASES:
        return TEAM_ALIASES[candidate]
    # Step 6: Fuzzy match
    fuzzy = _fuzzy_match(key)
    if fuzzy is not None:
        return fuzzy
    # Step 7: Fallback
    return norm if norm else key

# ============================================================
# build_canonical_id — generate canonical match ID
# ============================================================

def build_canonical_id(home_team: str, away_team: str, date_utc: str) -> str:
    """
    Build canonical match ID from team names and date.
    Format: {home_clean}__{away_clean}__{YYYYMMDD}
    Per §1.18, §3 of architectural guide.
    """
    home_clean = clean_team_name(home_team)
    away_clean = clean_team_name(away_team)

    # Extract YYYYMMDD from date_utc (ISO 8601)
    date_str = ""
    if date_utc:
        date_part = date_utc.strip()[:10]
        if len(date_part) >= 10 and date_part[4] == "-" and date_part[7] == "-":
            date_str = date_part[:4] + date_part[5:7] + date_part[8:10]

    if not home_clean or not away_clean:
        return ""
    if not date_str:
        return ""

    return f"{home_clean}__{away_clean}__{date_str}"


